.n3d-scene { perspective: 640px; perspective-origin: 50% 42%; display: flex; align-items: center; justify-content: center; min-height: 150px; }
.n3d-mesh { width: 190px; height: 120px; transform-style: preserve-3d; transform: rotateX(58deg) rotateZ(-30deg); animation: 11s ease-in-out 0s infinite normal none running n3dTilt; }
.n3d-mesh svg { width: 190px; height: 120px; }
.n3d-mesh path { opacity: 0; animation: 1s ease-out 0s 1 normal forwards running ncx2Fade; }
.n3d-mesh line { stroke: rgba(var(--info-rgb),.5); }
@keyframes n3dTilt { 
  0%, 100% { transform: rotateX(52deg) rotateZ(-4deg); }
  50% { transform: rotateX(52deg) rotateZ(6deg); }
}
@keyframes ncx2Fade { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}

.seg { display: flex; gap: 4px; width: 210px; }
.seg > i { flex: 1 1 0%; height: 12px; border-radius: 3px; background: var(--panel2); border: 1px solid var(--line); }
.seg > i.on { background: var(--accent); border-color: var(--accent); }
.n3d-scene { perspective: 640px; perspective-origin: 50% 42%; display: flex; align-items: center; justify-content: center; min-height: 150px; }
.n3d-stack .seg { position: relative; width: 30px; transform-style: preserve-3d; transform-origin: center bottom; animation: 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0s 1 normal both running n3dRise; }
.n3d-stack .seg span { position: absolute; left: 0px; top: 0px; }
.n3d-ribbon { position: relative; width: 180px; height: 100px; transform-style: preserve-3d; transform: rotateX(20deg) rotateY(-24deg); animation: 9s ease-in-out 0s infinite normal none running n3dSway; }
.n3d-ribbon .seg { position: absolute; bottom: 30px; width: 14px; height: 6px; transform-style: preserve-3d; animation: 0.7s ease-out 0s 1 normal both running ncx2Fade; }
.n3d-ribbon .seg .top { position: absolute; inset: 0px; background: linear-gradient(90deg,var(--info),var(--accent)); transform-origin: center bottom; transform: rotateX(-90deg); }
.ncx2-arcgauge .seg { fill: none; stroke-width: 12; stroke-linecap: round; stroke-dasharray: var(--dash) 999; stroke-dashoffset: var(--dash); animation: 1.6s ease-out 0s 1 normal forwards running ncx2Draw; }
@keyframes n3dRise { 
  0% { transform: scaleY(0); }
  100% { transform: scaleY(1); }
}
@keyframes n3dSway { 
  0%, 100% { transform: rotateX(13deg) rotateY(-26deg); }
  50% { transform: rotateX(15deg) rotateY(-6deg); }
}
@keyframes ncx2Draw { 
  100% { stroke-dashoffset: 0; }
}
@keyframes ncx2Fade { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}

.ncx2-violin svg { width: 200px; height: 110px; }
.ncx2-violin path { fill: rgba(var(--info-rgb),.28); stroke: var(--info); stroke-width: 1.5; transform-origin: center center; animation: 0.9s ease-out 0s 1 normal both running ncx2Grow; }
.ncx2-violin line { stroke: var(--ink); stroke-width: 2; }
.ncx2-violin circle { fill: var(--accent); }
@keyframes ncx2Grow { 
  0% { transform: scaleY(0); }
  100% { transform: scaleY(1); }
}

.nch-pctband .med { fill: none; stroke: var(--accent); stroke-width: 2.5; stroke-dasharray: 400; stroke-dashoffset: 400; animation: 2.6s ease-out 0s infinite normal none running nchDraw; }
@keyframes nchDraw { 
  100% { stroke-dashoffset: 0; }
}
.ncx2-box { display: flex; align-items: flex-end; gap: 16px; height: 110px; }
.ncx2-box .bx { position: relative; width: 26px; height: 100%; }
.ncx2-box .whk { position: absolute; left: 50%; width: 2px; background: var(--muted); transform: translateX(-50%); }
.ncx2-box .cap { position: absolute; left: 20%; right: 20%; height: 2px; background: var(--muted); }
.ncx2-box .iqr { position: absolute; left: 0px; right: 0px; border: 1.5px solid var(--info); background: rgba(var(--info-rgb),.25); border-radius: 3px; transform-origin: center center; animation: 0.9s ease-out 0s 1 normal both running ncx2Grow; }
