.lv-ecg .val { position: absolute; top: 7px; right: 9px; font-style: normal; font-variant: tabular-nums; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 800; font-stretch: normal; font-size: 13px; line-height: normal; font-family: ui-monospace, Menlo, monospace; color: var(--ink); }
.nch-gantt .row { height: 12px; background: var(--panel2); border-radius: 6px; position: relative; overflow: hidden; }
