.ncx2-bullet .val { position: absolute; left: 0px; top: 4px; height: 8px; border-radius: 3px; background: var(--ink); transform-origin: left center; animation: 1.1s ease-out 0s 1 normal both running ncx2GrowX; }
.ncx2-bullet .tgt { position: absolute; top: -2px; width: 3px; height: 20px; background: var(--accent); }
