.gallery :is(.brut-nav, .brut-drop, .brut-ctx, .brut-tabs, .brut-btn, .brut-toast, .brut-banner, .brut-callout, .brut-quote, .brut-bars, .brut-kpi, .brut-meter, .brut-table, .brut-field, .brut-check, .brut-headline, .brut-marked, .brut-stamp-text, .brut-badge, .brut-avatar, .brut-swatch-row) { --ink: #111111; --paper: #f2f2f0; --hot: #ffe600; --danger: #ff2e00; font-family: "Courier New", ui-monospace, SFMono-Regular, Menlo, monospace; color: var(--ink); }
