.brut-nav { display: flex; background: var(--paper); border: 3px solid var(--ink); box-shadow: 6px 6px 0 var(--ink); }
.brut-navlink { padding: 10px 14px; text-decoration: none; color: var(--ink); font-weight: 800; font-size: 12px; letter-spacing: 0.06em; border-right: 3px solid var(--ink); }
